def make_all_conditional_lora_config(
    emb_input_features,
    hidden_dim=256,
    hidden_layers=1,
    lora_dropout=0.01,
    lora_scale=1,
    embedding_dropout=0,
    except_output_head=False,
    emb_attn_pooling=False,
):
    """Conditional LoRA only on the output heads; the backbone is conditioned through the state decoder instead."""
    shared_config = {
        "emb_input_features": emb_input_features,
        "hidden_dim": hidden_dim,
        "hidden_layers": hidden_layers,
        "lora_dropout": lora_dropout,
        "embedding_dropout": embedding_dropout,
        "lora_scale": lora_scale,
        "convert_conv": True,
        "convert_linear": True,
        "emb_attn_pooling": emb_attn_pooling,
    }
    lora_config = {
        "final_output_head": {
            **shared_config,
            "lora_rank": 1,
        },
        "delta_output_head": {
            **shared_config,
            "lora_rank": 1,
        },
        "gene_count_output_head": {
            **shared_config,
            "lora_rank": 1,
        },
    }

    if except_output_head:
        del lora_config["final_output_head"]

    return lora_config

