import math
import torch.nn.functional as F


class StateKVMemory(nn.Module):
    """Residual key-value memory: the cell state generates which patterns are read (keys) and what is written (values)."""

    def __init__(self, channels, gen_dim, slots=128):
        super().__init__()
        self.channels = int(channels)
        self.slots = int(slots)
        c, m = self.channels, self.slots
        self.key0 = nn.Parameter(torch.randn(m, c))
        self.key_gen = nn.Linear(gen_dim, m * c)
        nn.init.normal_(self.key_gen.weight, std=0.5 / math.sqrt(gen_dim))
        nn.init.zeros_(self.key_gen.bias)
        self.kbias = nn.Linear(gen_dim, m)
        nn.init.zeros_(self.kbias.weight)
        nn.init.zeros_(self.kbias.bias)
        self.val0 = nn.Parameter(torch.zeros(c, m))
        self.val_gen = nn.Linear(gen_dim, c * m)
        nn.init.zeros_(self.val_gen.weight)
        nn.init.zeros_(self.val_gen.bias)

    def forward(self, h, z):
        b, c, _ = h.shape
        if c != self.channels:
            return h
        dt = h.dtype
        zf = z.float()
        k = self.key0.unsqueeze(0).float() + self.key_gen(zf).float().view(b, self.slots, c)
        v = self.val0.unsqueeze(0).float() + self.val_gen(zf).float().view(b, c, self.slots)
        kb = self.kbias(zf).float().unsqueeze(-1)
        h32 = h.float()
        mean = h32.mean(dim=1, keepdim=True)
        var = h32.var(dim=1, keepdim=True, unbiased=False)
        u = ((h32 - mean) * torch.rsqrt(var + 1e-5)).to(dt)
        pre = torch.einsum("bmc,bcl->bml", k.to(dt), u) / math.sqrt(c)
        a = F.gelu(pre + kb.to(dt))
        out = torch.einsum("bcm,bml->bcl", v.to(dt), a) / math.sqrt(self.slots)
        return h + out.to(dt)


class ConditionedBorzoi(BorzoiLoRA):
    default_config = BorzoiLoRA.default_config.copy()

    def freeze_all_parameter_except_output_head(self):
        """Freeze all parameters except the final output head (unfrozen again in convert_to_lora)."""
        for name, param in self.named_parameters():
            if "output_head" in name:
                continue
            if "cond_emb_module" in name:
                continue
            if "signal_encoder" in name:
                continue
            param.requires_grad = False
        return

    def convert_to_lora(self):
        """No LoRA: the whole backbone is fine-tuned; the state acts through key-value memories."""
        self._part_mode_d = {}
        for p in self.parameters():
            p.requires_grad = True
        self._build_state_memory()
        for p in self.parameters():
            p.requires_grad = True
        return

    def _model_device(self):
        for name, p in self.named_parameters():
            return p.device
        return torch.device("cpu")

    def _part(self, name, x, *args, **kwargs):
        mod = getattr(self, name)
        modes = getattr(self, "_part_mode_d", None)
        if modes is None:
            self._part_mode_d = {}
            modes = self._part_mode_d
        mode = modes.get(name)
        if mode is None:
            try:
                out = mod(x, *args, **kwargs)
                modes[name] = True
                return out
            except TypeError:
                modes[name] = False
                return mod(x)
        if mode:
            return mod(x, *args, **kwargs)
        return mod(x)

    def _build_state_memory(self):
        dev = self._model_device()
        self.to(dev)
        emb_dim = int(self.cond_emb_module.output_dim)
        self._probe_dims = []
        was_training = self.training
        self.eval()
        x = torch.zeros(1, 4, 524288, device=dev)
        x[:, 0, :] = 1.0
        emb = torch.zeros(1, emb_dim, device=dev)
        with torch.no_grad():
            with torch.autocast(
                device_type=dev.type,
                dtype=torch.bfloat16,
                enabled=(dev.type == "cuda"),
            ):
                self.forward_signal_model(x, None, emb, crop=True)
        dims = list(self._probe_dims)
        self._probe_dims = None
        self.train(was_training)
        del x, emb

        gen_dim = 64
        self.state_trunk = nn.Sequential(
            nn.Linear(emb_dim, 256),
            nn.SiLU(),
            nn.Linear(256, gen_dim),
            nn.LayerNorm(gen_dim),
        )
        self.state_mem = nn.ModuleList(
            [StateKVMemory(c, gen_dim, slots=128) for c in dims]
        )
        self.state_trunk.to(dev)
        self.state_mem.to(dev)
        print("State KV memories built with channel widths", dims)
        return

    def _state_code(self, embedding):
        mems = getattr(self, "state_mem", None)
        if mems is None or embedding is None:
            return None
        if embedding.ndim == 3:
            embedding = embedding.mean(dim=1)
        return self.state_trunk(embedding.float())

    def _mem(self, idx, h, z):
        mems = getattr(self, "state_mem", None)
        if mems is None or z is None:
            dims = getattr(self, "_probe_dims", None)
            if dims is not None:
                dims.append(int(h.shape[1]))
            return h
        return mems[idx](h, z)

    def forward_signal_model(
        self,
        x,
        signal,
        embedding,
        crop=True,
        return_dna_embedding=False,
        gene_mask=None,
    ):
        """Forward pass with DNA and signal input."""
        x = self._autocast_dtype(x)
        signal = self._autocast_dtype(signal)
        z = self._state_code(embedding)

        x = self._part("conv_dna", x, embedding=embedding, gene_mask=gene_mask)

        x_unet0 = self._part("res_tower", x, embedding)

        if signal is not None:
            use_signal = True
            if self.nosignal_prob > 0.0 and self.training:
                use_signal = torch.rand(1)[0] > self.nosignal_prob
            if use_signal:
                sig_emb = self.signal_encoder(signal)
                x_unet0 = x_unet0 + sig_emb

        x_unet1 = self._part("unet1", x_unet0, embedding)
        x = self._max_pool(x_unet1)
        x_unet0 = self._part("horizontal_conv0", x_unet0, embedding)
        x_unet1 = self._part("horizontal_conv1", x_unet1, embedding)
        x = self._part("transformer", x.permute(0, 2, 1), embedding)
        x = x.permute(0, 2, 1)
        x = self._mem(0, x, z)
        x = self._part("upsampling_unet1", x, embedding)
        x = x + x_unet1
        x = self._part("separable1", x, embedding)
        x = self._mem(1, x, z)
        x = self._part("upsampling_unet0", x, embedding)
        x = x + x_unet0
        x = self._part("separable0", x, embedding)
        x = self._mem(2, x, z)
        x = self._part("final_joined_convs", x, embedding)
        x = self._mem(3, x, z)

        if crop:
            x = self.crop(x)

        output = self._part("final_output_head", x, embedding=embedding)

        if return_dna_embedding:
            return output, x
        return output

# --- block: training ---
class TrainingRecipe:
    """How the searched model is trained. Mixed into Bolero's trainer (BorzoiLoRATrainer); the trainer calls these."""

    def _get_scheduler(self, optimizer):
        self.config["scheduler_type"] = "borzoi"
        warmup_steps = self.config.get("warmup_steps", 5000)
        accumulate_grad = self.config.get("accumulate_grad", 1)
        warmup_steps = warmup_steps // accumulate_grad + 1
        total_steps = self.config.get("lr_total_steps", 250000)
        total_steps = total_steps // accumulate_grad + 1
        scheduler = GenericTrainer._get_scheduler(
            self, optimizer, warmup_steps=warmup_steps, total_steps=total_steps
        )
        return scheduler

    def _fine_grained_lr_groups(self):
        """Low lr for the pretrained backbone, standard lr for heads/encoders, higher lr for the state memories."""
        standard_lr = self.config["lr"]
        backbone_lr = self.config.get("backbone_lr", 2e-5)
        state_lr = self.config.get("state_lr", 2.5e-4)
        wd = self.config["weight_decay"]
        standard_group = []
        backbone_group = []
        state_group = []
        for name, param in self.model.named_parameters():
            if not param.requires_grad:
                continue
            if "state_mem" in name or "state_trunk" in name:
                state_group.append(param)
            elif (
                "output_head" in name
                or "cond_emb_module" in name
                or "signal_encoder" in name
            ):
                standard_group.append(param)
            else:
                backbone_group.append(param)
        parameters = []
        if len(standard_group) > 0:
            parameters.append(
                {"params": standard_group, "weight_decay": wd, "lr": standard_lr}
            )
        if len(backbone_group) > 0:
            parameters.append(
                {"params": backbone_group, "weight_decay": wd, "lr": backbone_lr}
            )
        if len(state_group) > 0:
            parameters.append(
                {"params": state_group, "weight_decay": wd, "lr": state_lr}
            )
        return parameters

    def _get_optimizer(self):
        optimizer_type = self.config["optimizer"]
        parameter_groups = self._fine_grained_lr_groups()
        if optimizer_type == "adamw":
            optimizer = torch.optim.AdamW(parameter_groups)
        elif optimizer_type == "adam":
            optimizer = torch.optim.Adam(parameter_groups)
        else:
            raise ValueError(f"Unknown optimizer type: {optimizer_type}")
        return optimizer

    def transform_batch(self, batch):
        """Applied to each training batch before the forward pass (augmentation); not to validation or scoring."""
        return batch

# --- block: embedding_mlp ---
class EmbeddingMLP(nn.Module, ArchEmbeddingMixin):
    """
    This class turn the input embedding into one of the LoRA low-rank weight matrix (A or B) through a simple MLP.
    """

    def __init__(
        self,
        input_features: int,
        output_features: int,
        output_shape: torch.Size,
        hidden_dim: int | list,
        hidden_layers: int = 0,
        norm_type="layer",
        batchnorm_momentum=0.1,
        dropout=0.0,
        residual=False,
        attn_pooling=False,
    ) -> None:
        """
        Initialize the EmbeddingMLP module.

        Args:
            input_features (int): The number of input features, usually the Encoder's embedding dimension.
            output_features (int): The number of output features, usually the number of parameters in the LoRA A or B matrix.
            hidden_dim (int): The number of hidden dimensions in the MLP.
            hidden_layers (int): The number of hidden layers in the MLP. Default is 0.
        """
        super().__init__()

        self.input_features = input_features
        if hidden_dim is None:
            hidden_dim = self.input_features
        if isinstance(hidden_dim, int):
            hidden_dim = [hidden_dim] * (hidden_layers + 1)
        assert (
            len(hidden_dim) == hidden_layers + 1
        ), "hidden_dim must match hidden_layers"
        self.hidden_dim = hidden_dim

        self.out_feathres = output_features
        self.output_shape = output_shape
        self.norm_type = norm_type
        self.batchnorm_momentum = batchnorm_momentum
        self.residual = residual
        self.dropout = dropout

        # MLP layers
        layers = [self._generate_linear_module(self.input_features, self.hidden_dim[0])]
        for idx in range(hidden_layers):
            in_features = self.hidden_dim[idx]
            out_features = self.hidden_dim[idx + 1]

            layers.append(
                self._generate_linear_module(
                    in_features=in_features, out_features=out_features
                )
            )
        layers.append(
            nn.Linear(in_features=self.hidden_dim[-1], out_features=self.out_feathres)
        )
        self.mlp = nn.Sequential(*layers)

        self.arch_features = 0

        if attn_pooling:
            self.attn_pooling = AttentionPooling(self.input_features)
        else:
            self.attn_pooling = None
        return

    def _generate_linear_module(self, in_features, out_features):
        if self.norm_type == "batch":
            norm = nn.BatchNorm1d(out_features, momentum=self.batchnorm_momentum)
        elif self.norm_type == "layer":
            norm = nn.LayerNorm(out_features)
        elif self.norm_type == "none":
            norm = nn.Identity()
        else:
            raise ValueError(f"Unknown norm type {self.norm_type}")

        layers = nn.Sequential(
            nn.Linear(in_features=in_features, out_features=out_features, bias=True),
            norm,
            nn.GELU(),
        )
        if self.dropout > 0:
            layers.append(nn.Dropout(self.dropout))

        if self.residual:
            # only add residual connection if the input and output features are the same
            if in_features == out_features:
                layers = Residual(layers)
        return layers

    def forward_mlp_with_arch(self, x):
        """Forward pass of the MLP with arch features."""
        # split the embedding into the original embedding and the arch features
        n_emb = x.shape[-1]
        n_arch = self.arch_features
        x, arch = torch.split(x, [n_emb - n_arch, n_arch], dim=-1)

        # forward pass through the MLP layers
        for layer in self.mlp:
            if isinstance(layer, ArchLinear):
                x = layer(x, arch)
            elif isinstance(layer, nn.Sequential):
                for sublayer in layer:
                    if isinstance(sublayer, ArchLinear):
                        x = sublayer(x, arch)
                    else:
                        x = sublayer(x)
            else:
                x = layer(x)
        return x

    def forward(self, embedding: torch.Tensor) -> torch.Tensor:
        """
        Forward pass of the EmbeddingMLP module.

        Args:
            embedding (torch.Tensor): The input embedding tensor.
                If the input tensor is 2D, it is assumed to be (bs, emb_dim).
                If the input tensor is 3D, it is assumed to be (bs, seq_len, emb_dim).

        Returns
        -------
            torch.Tensor: The output tensor after passing through the MLP layers.
        """
        if embedding.ndim == 3:
            # expect input embedding shape (bs, l, d)
            if self.attn_pooling is not None:
                embedding = self.attn_pooling(embedding)  # (bs, l, d) -> (bs, d)
            else:
                embedding = embedding.mean(dim=1)

        if self.arch_features > 0:
            x = self.forward_mlp_with_arch(embedding)
        else:
            x = self.mlp(embedding)

        a, b = self.output_shape
        x = rearrange(x, "bs (a b) -> bs a b", a=a, b=b)
        return x

    def zero_weights_and_bias(self):
        """
        Zero the weights and bias of the MLP's last layer, use this in B embedding.
        """
        last_layer = self.mlp[-1]

        assert isinstance(
            last_layer, nn.Linear
        ), f"Last layer is {type(last_layer)}, expected nn.Linear"
        if last_layer.bias is not None:
            last_layer.bias.data[...] = 0
        last_layer.weight.data[...] = 0
        return

    def fix_parameters(self):
        """
        Fix the parameters of the MLP.
        """
        for param in self.parameters():
            param.requires_grad = False
        return

# --- block: state_encoder ---
class _SimpleEncoder(nn.Module):
    """
    _SimpleEncoder class handles encoder network for single datasets.
    """

    def __init__(
        self,
        input_dim: int,
        encoder_dims: list[int],
        encoder_dropout: float,
        attn_pooling: bool = False,
        norm_type: str | None = None,
    ):
        super().__init__()
        self.input_dim = input_dim
        self.encoder_dims = encoder_dims
        self.encoder_dropout = encoder_dropout

        layers = []
        _dims = [self.input_dim] + self.encoder_dims
        for i in range(len(_dims) - 1):
            layers.append(nn.Linear(_dims[i], _dims[i + 1]))
            if norm_type == "layer":
                layers.append(nn.LayerNorm(_dims[i + 1]))
            elif norm_type == "batch":
                layers.append(nn.BatchNorm1d(_dims[i + 1]))
            else:
                assert norm_type in (None, "none"), f"Unknown norm type {norm_type}"
            layers.append(nn.SiLU())
            if self.encoder_dropout > 0:
                layers.append(nn.Dropout(self.encoder_dropout))
        self.layers = nn.Sequential(*layers)
        if attn_pooling:
            self.attn_pooling = AttentionPooling(_dims[-1])
        else:
            self.attn_pooling = None

        self.output_dim = _dims[-1]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (bs, ..., d_in) or (bs, ..., d_in)

        return: (bs, ..., d_out)
        """
        if x.ndim == 3:
            attn_mask = self.attn_pooling._make_all_zero_mask(x)
        x = self.layers(x)

        if x.ndim == 3:
            if self.attn_pooling is not None:
                # expect input embedding shape (bs, l, d)
                x = self.attn_pooling(x, attn_mask)
            else:
                # if not attn_pooling in encoder,
                # here just perform mean pooling on the condition embedding
                x = x.mean(dim=1)
        return x  # shape (bs, d)


class _SimpleEncoderDict(nn.ModuleDict):
    def __init__(
        self,
        input_dims: dict[str:int],
        encoder_dims: list[int],
        encoder_dropout: float,
        attn_pooling: bool = False,
        norm_type: str | None = None,
        pool_mode="concat",
    ):
        _dict = {
            key: _SimpleEncoder(
                input_dim,
                encoder_dims=encoder_dims,
                encoder_dropout=encoder_dropout,
                attn_pooling=attn_pooling,
                norm_type=norm_type,
            )
            for key, input_dim in input_dims.items()
        }
        self.pool_mode = pool_mode
        super().__init__(_dict)

        if pool_mode == "concat":
            self.output_dim = encoder_dims[-1] * len(_dict)
        else:
            self.output_dim = encoder_dims[-1]

    def forward(self, input_emb: dict[str, torch.Tensor]):
        assert isinstance(
            input_emb, dict
        ), f"input_emb must be dict, but got {type(input_emb)}"
        try:
            out_emb = [_encoder(input_emb[k]) for k, _encoder in self.items()]
        except KeyError:
            raise KeyError(
                f"input_emb must have keys {list(self.keys())}, but got {list(input_emb.keys())}"
            ) from None
        if self.pool_mode == "concat":
            out_emb = torch.cat(out_emb, dim=-1)
        else:
            # sum out emb
            out_emb = torch.stack(out_emb).mean(dim=0)
        return out_emb


def _create_encoder(
    emb_dim: int | dict[int],
    encoder_dims: list[int],
    encoder_dropout: float,
    attn_pooling: bool,
    norm_type: str | None = None,
    pool_mode: str = "concat",
) -> tuple[nn.Module | nn.ModuleDict, int]:
    encoder_kwargs = {
        "encoder_dims": encoder_dims,
        "encoder_dropout": encoder_dropout,
        "attn_pooling": attn_pooling,
        "norm_type": norm_type,
    }

    # condition encoder
    if isinstance(emb_dim, int):
        encoder = _SimpleEncoder(input_dim=emb_dim, **encoder_kwargs)
        enc_output_dim = encoder.output_dim
    elif isinstance(emb_dim, dict):
        encoder = _SimpleEncoderDict(
            input_dims=emb_dim, pool_mode=pool_mode, **encoder_kwargs
        )
        enc_output_dim = encoder.output_dim
    else:
        encoder = None
        enc_output_dim = 0
    return encoder, enc_output_dim


class ConditionEmbeddingModule(nn.Module):
    """
    ConditionEmbeddingModule is a module that combines multiple embedding sources
    (cell emb, cond emb) into single hidden embedding.
    """

    def __init__(
        self,
        cell_emb_dim: int,
        cond_emb_dim: int | dict[int] | None,
        cell_encoder_dims: list[int] = (256, 256),
        cell_encoder_dropout: float = 0.1,
        cell_attn_pooling: bool = True,
        cond_encoder_dims: list[int] = (256, 256),
        cond_encoder_dropout: float = 0.1,
        cond_attn_pooling: bool = True,
    ):
        super().__init__()

        cell_encoder_dims = list(cell_encoder_dims)
        cond_encoder_dims = list(cond_encoder_dims)

        # cell embedding encoder
        self.cell_encoder, cell_out_dim = _create_encoder(
            emb_dim=cell_emb_dim,
            encoder_dims=cell_encoder_dims,
            encoder_dropout=cell_encoder_dropout,
            attn_pooling=cell_attn_pooling,
        )

        self.cond_encoder, cond_out_dim = _create_encoder(
            emb_dim=cond_emb_dim,
            encoder_dims=cond_encoder_dims,
            encoder_dropout=cond_encoder_dropout,
            attn_pooling=cond_attn_pooling,
        )
        if self.cond_encoder is None:
            print(
                f"cond_emb_dim ({cond_emb_dim}) is not int nor dict, no cond_encoder for the model."
            )

        self.output_dim = cell_out_dim + cond_out_dim
        return

    def forward(
        self,
        cell_emb: torch.Tensor,
        cond_emb: torch.Tensor | dict[str, torch.Tensor],
    ) -> torch.Tensor:
        """
        cell_emb: (bs, d_e) or (bs, n, d_e)
        cond_emb: (bs, d_c) or (bs, n, d_c)

        return: (bs, h_e + h_c)
        """
        # encode cell embedding
        cell_emb = self.cell_encoder(cell_emb)

        if self.cond_encoder is None:
            final_emb = cell_emb
        else:
            cond_emb = self.cond_encoder(cond_emb)
            final_emb = torch.cat([cell_emb, cond_emb], dim=-1)
        return final_emb

# --- block: conditional_lora ---
class ConditionalLoRALayer:
    def __init__(
        self,
        shape_a: torch.Size,
        shape_b: torch.Size,
        lora_alpha: int,
        lora_scale: int,
        lora_dropout: float,
        emb_input_features: int,
        hidden_dim: int,
        hidden_layers: int,
        norm_type: str = "layer",
        batchnorm_momentum: float = 0.1,
        embedding_dropout: float = 0.0,
        emb_attn_pooling: bool = False,
    ):
        self.base_class = nn.Module
        # Optional dropout
        if lora_dropout > 0.0:
            self.lora_dropout = nn.Dropout(p=lora_dropout)
        else:
            self.lora_dropout = nn.Identity()

        r_a, in_features = shape_a
        out_features, r_b = shape_b
        assert (
            r_a == r_b
        ), f"The ranks of A and B should be the same, but got {r_a} for a and {r_b} for b"
        self.r = r_a

        if lora_alpha is None:
            assert (
                lora_scale is not None
            ), "Either lora_alpha or lora_scale should be set"
            lora_alpha = self.r * lora_scale
        self.lora_alpha = lora_alpha

        # Actual trainable parameters
        self.lora_A_module = EmbeddingMLP(
            input_features=emb_input_features,
            output_features=self.r * in_features,
            output_shape=(self.r, in_features),
            hidden_dim=hidden_dim,
            hidden_layers=hidden_layers,
            norm_type=norm_type,
            batchnorm_momentum=batchnorm_momentum,
            dropout=embedding_dropout,
            attn_pooling=emb_attn_pooling,
        )
        self.lora_B_module = EmbeddingMLP(
            input_features=emb_input_features,
            output_features=out_features * self.r,
            output_shape=(out_features, self.r),
            hidden_dim=hidden_dim,
            hidden_layers=hidden_layers,
            norm_type=norm_type,
            batchnorm_momentum=batchnorm_momentum,
            dropout=embedding_dropout,
            attn_pooling=emb_attn_pooling,
        )
        self.scaling = self.lora_alpha / self.r

    def lora_A(self, *args, **kwargs) -> torch.Tensor:
        """Get the A module output."""
        return self.lora_A_module(*args, **kwargs)

    def lora_B(self, *args, **kwargs) -> torch.Tensor:
        """Get the B module output."""
        return self.lora_B_module(*args, **kwargs)

    def _lora_ab(self, *args, **kwargs):
        a = rearrange(self.lora_A(*args, **kwargs), "b r i -> b i r")
        b = rearrange(self.lora_B(*args, **kwargs), "b o r -> b r o")
        ab = einsum(a, b, "b i r, b r o -> b i o") * self.scaling
        return ab

    def reset_lora_parameters(self):
        """Reset the parameters of the LoRA layer."""
        # TODO: Maybe initialize the weights of the A module
        # Original LoRA uses kaiming_uniform initialization
        # nn.init.kaiming_uniform_(self.lora_A, a=math.sqrt(5))
        # Our lora_A is an MLP, this line below is used to scale the weights with the example embedding
        # self.lora_A_module.scale_weights(example_embedding)

        # Initialize the weights of the B module to zero
        self.lora_B_module.zero_weights_and_bias()

    def train(self, mode: bool = True):
        """Set the training mode of the LoRA layer."""
        self.base_class.train(self, mode)


class ConditionalLoRALinear(nn.Linear, ConditionalLoRALayer):
    # LoRA implemented in a dense layer
    def __init__(
        self,
        in_features: int,
        out_features: int,
        emb_input_features: int,
        hidden_dim: int,
        hidden_layers: int = 0,
        lora_rank: int = 1,
        lora_alpha: int = None,
        lora_scale: int = 1,
        lora_dropout: float = 0.0,
        norm_type="layer",
        batchnorm_momentum=0.1,
        embedding_dropout=0.0,
        reset_lora_in_init=True,
        emb_attn_pooling=False,
        **kwargs,
    ):
        self.base_class = nn.Linear
        nn.Linear.__init__(self, in_features, out_features, **kwargs)
        ConditionalLoRALayer.__init__(
            self,
            lora_alpha=lora_alpha,
            lora_scale=lora_scale,
            lora_dropout=lora_dropout,
            emb_input_features=emb_input_features,
            shape_a=torch.Size([lora_rank, in_features]),
            shape_b=torch.Size([out_features, lora_rank]),
            hidden_dim=hidden_dim,
            hidden_layers=hidden_layers,
            norm_type=norm_type,
            batchnorm_momentum=batchnorm_momentum,
            embedding_dropout=embedding_dropout,
            emb_attn_pooling=emb_attn_pooling,
        )

        # Freezing the pre-trained weight matrix
        self.weight.requires_grad = False

        nn.Linear.reset_parameters(self)

        if reset_lora_in_init:
            self.reset_lora_parameters()

    def _lora_adaptive_weight(self, *args, **kwargs):
        # (bs, i, o) -> (bs, o, i)
        lora_weight = self._lora_ab(*args, **kwargs).transpose(1, 2)
        # (o, i) -> (1, o, i)
        base_weight = rearrange(self.weight, "o i -> 1 o i")
        weight = lora_weight + base_weight
        return weight  # (bs, o, i)

    def _adaptive_weight(self, *args, **kwargs):
        weight = self._lora_adaptive_weight(*args, **kwargs)
        return weight  # (bs, o, i)

    def collapse(self, *args, **kwargs) -> nn.Linear:
        """Collapse the LoRA layer."""
        weight = self._adaptive_weight(*args, **kwargs).squeeze(0)

        # Create a new nn.Linear instance with the LoRA weights
        linear = nn.Linear(
            in_features=self.in_features,
            out_features=self.out_features,
            bias=self.bias is not None,
            device=self.weight.device,
            dtype=self.weight.dtype,
        )
        linear.weight.data = weight.data.clone()
        if self.bias is not None:
            linear.bias.data = self.bias.data.clone()
        return linear

    def forward(self, x: torch.Tensor, *args, **kwargs) -> torch.Tensor:
        """Forward pass of the LoRA layer."""
        # weight: (bs, o, i)
        weight = self._adaptive_weight(*args, **kwargs)

        # vectorized linear operation on each item in the batch
        lora_result = einsum(x, weight, "b ... i, b o i -> b ... o")
        if self.bias is not None:
            lora_result += self.bias
        lora_result = self.lora_dropout(lora_result)
        return lora_result

    @classmethod
    def from_nn(
        cls,
        linear_module: nn.Linear,
        **kwargs,
    ) -> "ConditionalLoRALinear":
        """
        Create a LoRALinear instance from an existing nn.Linear module.
        """
        lora_linear = cls(
            in_features=linear_module.in_features,
            out_features=linear_module.out_features,
            bias=linear_module.bias is not None,
            device=linear_module.weight.device,
            dtype=linear_module.weight.dtype,
            **kwargs,
        )

        # Copy the original weight and bias to the new LoRALinear instance
        lora_linear.weight.data = linear_module.weight.data.clone()
        if linear_module.bias is not None:
            lora_linear.bias.data = linear_module.bias.data.clone()
        return lora_linear


class ConditionalLoRAConv(nn.Module, ConditionalLoRALayer):
    def __init__(
        self,
        conv_class,
        in_channels,
        out_channels,
        kernel_size,
        groups,
        emb_input_features: int,
        hidden_dim: int,
        lora_rank=2,
        lora_alpha=None,
        lora_scale=1,
        lora_dropout=0.0,
        hidden_layers: int = 0,
        norm_type="layer",
        batchnorm_momentum=0.1,
        embedding_dropout=0.0,
        reset_lora_in_init=True,
        emb_attn_pooling=False,
        **kwargs,
    ):
        if issubclass(conv_class, nn.Conv1d):
            conv_type = "1d"
            shape_a, shape_b = self._gen_conv1d_lora_shape(
                in_channels, out_channels, groups, kernel_size, lora_rank
            )
        elif issubclass(conv_class, nn.Conv2d):
            conv_type = "2d"
            shape_a, shape_b = self._gen_conv2d_lora_shape(
                in_channels, out_channels, groups, kernel_size, lora_rank
            )
        elif issubclass(conv_class, nn.Conv3d):
            conv_type = "3d"
            shape_a, shape_b = self._gen_conv3d_lora_shape(
                in_channels, out_channels, groups, kernel_size, lora_rank
            )
        else:
            raise ValueError(f"Unsupported convolution module class {conv_class}")

        self.base_class = conv_class
        self.conv_type = conv_type

        super().__init__()
        self.conv = conv_class(
            in_channels=in_channels,
            out_channels=out_channels,
            kernel_size=kernel_size,
            groups=groups,
            **kwargs,
        )
        self.weight = self.conv.weight
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.groups = groups

        assert isinstance(kernel_size, int), "Only square kernels are supported"

        ConditionalLoRALayer.__init__(
            self,
            shape_a=shape_a,
            shape_b=shape_b,
            lora_alpha=lora_alpha,
            lora_scale=lora_scale,
            lora_dropout=lora_dropout,
            emb_input_features=emb_input_features,
            hidden_dim=hidden_dim,
            hidden_layers=hidden_layers,
            norm_type=norm_type,
            batchnorm_momentum=batchnorm_momentum,
            embedding_dropout=embedding_dropout,
            emb_attn_pooling=emb_attn_pooling,
        )

        # Freezing the pre-trained weight matrix
        self.conv.weight.requires_grad = False

        self.conv.reset_parameters()

        if reset_lora_in_init:
            self.reset_lora_parameters()

    def _gen_conv1d_lora_shape(self, in_channels, out_channels, groups, kernel_size, r):
        shape_a = (r * kernel_size, in_channels // groups * kernel_size)
        shape_b = (out_channels, r * kernel_size)
        return shape_a, shape_b

    def _gen_conv2d_lora_shape(self, in_channels, out_channels, groups, kernel_size, r):
        shape_a = (r * kernel_size, in_channels // groups * kernel_size)
        shape_b = (out_channels * kernel_size, r * kernel_size)
        return shape_a, shape_b

    def _gen_conv3d_lora_shape(self, in_channels, out_channels, groups, kernel_size, r):
        raise NotImplementedError

    def _lora_ab(self, *args, **kwargs):
        lora_weights = super()._lora_ab(*args, **kwargs)
        _i = self.in_channels // self.groups
        _o = self.out_channels
        _k = self.kernel_size
        if self.conv_type == "1d":
            lora_weights = rearrange(lora_weights, "b (i k) o -> b o i k", i=_i, k=_k)
        elif self.conv_type == "2d":
            lora_weights = rearrange(
                lora_weights, "b (i k1) (o k2) -> b o i k1 k2", i=_i, o=_o, k1=_k, k2=_k
            )
        elif self.conv_type == "3d":
            raise NotImplementedError
        return lora_weights

    def _prepare_conv1d_lora(self, x, *args, **kwargs):
        """
        Get the LoRA added weights for a 1D convolution.

        Returns
        -------
            torch.Tensor: The LoRA added weights with shape (batch_size * out_channels, in_channels, kernel_size).
        """
        lora_weights = self._lora_ab(*args, **kwargs)
        base_weights = rearrange(self.conv.weight, "o i k -> 1 o i k")
        weights = base_weights + lora_weights
        weights = rearrange(weights, "b o i k -> (b o) i k")

        b = x.shape[0]
        x = rearrange(x, "b i l -> 1 (b i) l")

        f_conv = F.conv1d
        revert_x = lambda x: rearrange(x, "1 (b i) l -> b i l", b=b)
        return x, weights, f_conv, revert_x

    def _prepare_conv2d_lora(self, x, *args, **kwargs) -> torch.Tensor:
        """
        Get the LoRA added weights for a 2D convolution.

        Returns
        -------
            torch.Tensor: The LoRA added weights with shape (batch_size * out_channels, in_channels, kernel_size, kernel_size).
        """
        lora_weights = self._lora_ab(*args, **kwargs)
        base_weights = rearrange(self.conv.weight, "o i k1 k2 -> 1 o i k1 k2")
        weights = rearrange(base_weights + lora_weights, "b o i k1 k2 -> (b o) i k1 k2")

        b = x.shape[0]
        x = rearrange(x, "b i h w -> 1 (b i) h w")

        f_conv = F.conv2d
        revert_x = lambda x: rearrange(x, "1 (b i) h w -> b i h w", b=b)
        return x, weights, f_conv, revert_x

    def _prepare_conv3d_lora(self, *args, **kwargs):
        raise NotImplementedError

    def collapse(self, *args, **kwargs) -> nn.modules.conv._ConvNd:
        """Collapse the LoRA layer."""
        new_conv = deepcopy(self.conv)
        new_conv.weight.data = self.conv.weight + self._lora_ab(
            *args, **kwargs
        ).reshape(self.conv.weight.shape)
        return new_conv

    def forward(self, x, *args, **kwargs):
        """Forward pass of the LoRA layer."""
        bs = x.shape[0]

        if self.conv_type == "1d":
            x, lora_weights, f_conv, revert_x = self._prepare_conv1d_lora(
                x, *args, **kwargs
            )
        elif self.conv_type == "2d":
            x, lora_weights, f_conv, revert_x = self._prepare_conv2d_lora(
                x, *args, **kwargs
            )
        elif self.conv_type == "3d":
            x, lora_weights, f_conv, revert_x = self._prepare_conv3d_lora(
                x, *args, **kwargs
            )
        else:
            raise ValueError(f"Unsupported convolution module class {self.conv_type}")

        # X shape (1, batch_size * layer_dim_in, ...)
        # weight shape (batch_size * layer_dim_out, layer_dim_in / groups, kernel_size ...)
        # within each group, the convolution projects from (layer_dim_in, ...) to (layer_dim_out, ...)
        # This way we vectorized the convolution operation when weight contains batch_size dimension
        conv_x = f_conv(
            input=x,
            weight=lora_weights,
            bias=(
                repeat(self.conv.bias, "o -> (bs o)", bs=bs)
                if self.conv.bias is not None
                else None
            ),
            groups=bs * self.groups,  # each batch_size is a group
            dilation=self.conv.dilation,
            padding=self.conv.padding,
            stride=self.conv.stride,
        )
        # return result with shape (batch_size, out_channels, ...)
        conv_x = revert_x(conv_x)

        conv_x = self.lora_dropout(conv_x)
        return conv_x

    @classmethod
    def from_nn(
        cls,
        conv_module: nn.Conv1d | nn.Conv2d | nn.Conv3d,
        **kwargs,
    ) -> "ConditionalLoRAConv":
        """
        Create a LoRAConvND instance from an existing nn.Conv1d, nn.Conv2d, or nn.Conv3d module.
        """
        assert (
            isinstance(conv_module.kernel_size, int)
            or len(set(conv_module.kernel_size)) == 1
        ), f"Only square kernels are supported, got {conv_module.kernel_size}"
        kernel_size_int = (
            conv_module.kernel_size[0]
            if isinstance(conv_module.kernel_size, tuple)
            else conv_module.kernel_size
        )

        lora_conv = cls(
            conv_class=type(conv_module),
            in_channels=conv_module.in_channels,
            out_channels=conv_module.out_channels,
            kernel_size=kernel_size_int,
            groups=conv_module.groups,
            stride=conv_module.stride,
            padding=conv_module.padding,
            dilation=conv_module.dilation,
            bias=conv_module.bias is not None,
            device=conv_module.weight.device,
            dtype=conv_module.weight.dtype,
            **kwargs,
        )

        # Copy the original weight and bias to the new LoRAConv1d instance
        lora_conv.conv.weight.data = conv_module.weight.data.clone()
        if conv_module.bias is not None:
            lora_conv.conv.bias.data = conv_module.bias.data.clone()
        return lora_conv


def convert_to_conditional_lora_model(
    model,
    emb_input_features: int,
    hidden_dim: int = 256,
    hidden_layers: int = 0,
    convert_linear=False,
    convert_conv=False,
    convert_embedding=False,
    lora_rank=1,
    lora_alpha=None,
    lora_scale=1,
    lora_dropout=0.0,
    inplace=False,
    bias_learable=None,
    verbose=False,
    include_name_patterns: list = None,
    exclude_name_patterns: list = None,
    default_conditional: bool = True,
    include_cond_lora_patterns: list = None,
    exclude_cond_lora_patterns: list = None,
    **kwargs,
):
    """
    Replace all pytorch modules (parent class of the lora class)
    in the given model with lora modules.

    Args:
        model (nn.Module): The original PyTorch model.
        emb_input_features (int): The number of input features for the embedding.
        hidden_dim (int): The number of hidden dimensions in the MLP.
        hidden_layers (int): The number of hidden layers in the MLP. Default is 0.
        convert_linear (bool): If set to True, nn.Linear modules are replaced.
            Default is False.
        convert_conv (bool): If set to True, nn.Conv1d, nn.Conv2d, and nn.Conv3d
            modules are replaced. Default is False.
        rank (int): The rank for LoRA parameterization.
        alpha (float): The scaling factor for LoRA, default is rank * lora_scale.
        lora_dropout (float): The dropout rate for LoRA input.
        inplace (bool): If set to True, the original model is modified.
            Default is False.
        bias_trainable (str): If set to None, will not make any changes to the bias.
            If set to True, all biases are trainable.
            If set to False, only base model biases are freezed.
            Default is "none".
        verbose (bool): If set to True, print the conversion process.
            Default is False.
        include_name_patterns (list): A list of patterns to include in the LoRA conversion.
            Default is None.
        exclude_name_patterns (list): A list of patterns to exclude from the LoRA conversion.
            Default is None.
        default_conditional (bool): Whether use conditional LoRA conversion for names not matching
            include_cond_lora_patterns OR exclude_cond_lora_patterns.
            Default is True.
        include_cond_lora_patterns (list): A list of patterns to include in the conditional LoRA conversion.
            Default is ('.+',), which means all LoRA layers will be conditional.
        exclude_cond_lora_patterns (list): A list of patterns to exclude from the conditional LoRA conversion.
            Default is None.
        kwargs: Additional keyword arguments to pass to the LoRA modules' constructors.

    Returns
    -------
        nn.Module: The modified model with lora layers.
    """
    if not inplace:
        model = deepcopy(model)

    if exclude_name_patterns is None:
        exclude_name_patterns = []
    if include_name_patterns is None:
        include_name_patterns = []
    if exclude_cond_lora_patterns is None:
        exclude_cond_lora_patterns = []
    if include_cond_lora_patterns is None:
        include_cond_lora_patterns = []

    # Create a list of modules to modify
    modules_to_modify = []
    for name, module in model.named_modules():
        if name_in_patterns(name, exclude_name_patterns):
            continue

        if len(include_name_patterns) > 0:
            if not name_in_patterns(name, include_name_patterns):
                continue

        conditional = default_conditional
        if name_in_patterns(name, include_cond_lora_patterns):
            conditional = True
        if name_in_patterns(name, exclude_cond_lora_patterns):
            conditional = False

        if isinstance(module, nn.Linear) and convert_linear:
            lora_cls = ConditionalLoRALinear if conditional else LoRALinear
            modules_to_modify.append((name, module, lora_cls))
        elif (
            isinstance(module, nn.Conv1d | nn.Conv2d | nn.Conv3d | Conv1dWrapper)
            and convert_conv
        ):
            lora_cls = ConditionalLoRAConv if conditional else LoRAConv
            modules_to_modify.append((name, module, lora_cls))
        elif isinstance(module, nn.Embedding) and convert_embedding:
            if conditional:
                raise NotImplementedError(
                    "Conditional LoRA for nn.Embedding is not implemented yet."
                )
            lora_cls = LoRAEmbedding
            modules_to_modify.append((name, module, lora_cls))
        else:
            pass

    if lora_alpha is not None:
        lora_scale = None

    # Update the model with the modified modules
    for name, module, lora_cls in modules_to_modify:
        if issubclass(lora_cls, ConditionalLoRALayer):
            lora_module = lora_cls.from_nn(
                module,
                lora_rank=lora_rank,
                lora_alpha=lora_alpha,
                lora_scale=lora_scale,
                lora_dropout=lora_dropout,
                emb_input_features=emb_input_features,
                hidden_dim=hidden_dim,
                hidden_layers=hidden_layers,
                **kwargs,
            )
        else:
            lora_module = lora_cls.from_nn(
                module,
                lora_rank=lora_rank,
                lora_alpha=lora_alpha,
                lora_scale=lora_scale,
                lora_dropout=lora_dropout,
            )
        if verbose:
            print(
                f"Converting '{name}' <{type(module).__name__}> to <{lora_cls.__name__}> module"
            )
        set_submodule_by_name(model, name, lora_module)

    mark_only_lora_as_trainable(model, bias_learable=bias_learable)
    return model

